package com.adent.odontogram.domain;
import com.adent.shared.domain.BaseEntity; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="odontograms") public class Odontogram extends BaseEntity {
 @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="clinical_record_id",nullable=false) private UUID clinicalRecordId; @Column(name="patient_id") private UUID patientId; @Column(name="encounter_id") private UUID encounterId; @Column(name="version_no",nullable=false) private int versionNo; @Column(nullable=false,length=30) private String status="CURRENT"; @Column(name="recorded_at",nullable=false) private OffsetDateTime recordedAt=OffsetDateTime.now(); @Column(name="drawing_json",nullable=false,columnDefinition="text") private String drawingJson="[]"; @Column(columnDefinition="text") private String notes; @Column(name="recorded_by",length=80) private String recordedBy;
 public UUID getTenantId(){return tenantId;}public void setTenantId(UUID v){tenantId=v;}public UUID getClinicalRecordId(){return clinicalRecordId;}public void setClinicalRecordId(UUID v){clinicalRecordId=v;}public UUID getPatientId(){return patientId;}public void setPatientId(UUID v){patientId=v;}public UUID getEncounterId(){return encounterId;}public void setEncounterId(UUID v){encounterId=v;}public int getVersionNo(){return versionNo;}public void setVersionNo(int v){versionNo=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public OffsetDateTime getRecordedAt(){return recordedAt;}public void setRecordedAt(OffsetDateTime v){recordedAt=v;}public String getDrawingJson(){return drawingJson;}public void setDrawingJson(String v){drawingJson=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public String getRecordedBy(){return recordedBy;}public void setRecordedBy(String v){recordedBy=v;}
}
